    "崖口上插着一面「旗」。风吹了很久，它一动没动。": "崖の縁に「旗」が一本立っている。風はずっと吹いていたが、それは微動だにしなかった。",
    "崖壁上倒挂着一只天蝎王，比你见过的大三倍，尾巴上挂着碎石。": "崖壁にグライオンが逆さにぶら下がっている。見たこともない大きさで、尻尾には砕けた岩がぶら下がる。",
