    "弃牌：把牌弃进弃牌堆（牌堆抽空时会洗回来）。": "捨て札：カードを捨て札置き場へ捨てる（山札が尽きたときはシャッフルして戻ってくる）。",
    "弃牌：进弃牌堆，牌堆抽空时会洗净再抽回来。": "捨て札：捨て札置き場に入り、山札が尽きたときにシャッフルして再び引いてくる。",
