    "战绩": "戦績",
    "手印比你的大一圈，掌纹很深，指爪的位置和你不太一样。你按了一会儿，沙子顺着门缝往下漏，漏出来的还有一张压在门轴底下的卡 —— 像是他自己塞回去的。\n「手比我大。……不过这张我拿走咯。」\n幸运 +3，获得「{card}」。": "手形は自分のより一回り大きく、手のひらの筋は深くて、爪の位置も自分とは少し違う。しばらく押しあてていると、砂が扉の隙間からこぼれ落ち、扉の軸の下に挟まっていたカードも一緒に出てきた —— あの子が自分で押し戻したみたいに。\n「手はわたしより大きい。……でも、このカードはもらっていくね。」\n幸運 +3、「{card}」を獲得。",
    "手牌": "手札",
    "手牌上限 {n} 张，抽到手牌满就抽不动了（剩下的留在牌堆顶，不会丢）。": "手札の上限は {n} 枚。手札がいっぱいになるとそれ以上は引けず、残りは山札の上に置かれたまま消えない。",
    "手牌空了 —— 结束回合，下回合会重新抽牌。": "手札が空になった —— ターン終了で、次のターンにまたドローする。",
    "手牌里没有这张卡": "そのカードは手札にない",
    "手牌：当前能打出的牌。上限由敏捷决定，抽到手牌满就抽不动了（剩下的留在牌堆顶，不会丢）。": "手札：今出せるカード。上限は敏捷で決まり、手札が一杯になるともう引けない（余りは山札の一番上に残るので、消えはしない）。",
    "扎手也认了。": "チクチクされてもいい。",
    "打不出去通常不是卡住了：先看这里是不是 0，再看 AP 够不够。": "出せないのは大抵フリーズではない：まずここが 0 かどうか、次に AP が足りているかをチェックする。",
    "打个滚。": "転げ回る。",
    "打之前先算一下值不值。": "打つ前に、割に合うか計算しておく。",
    "打出去的牌进<code>弃牌区</code>；标着<code>销毁</code>的卡一场战斗只能用一次（进销毁区，不会洗回来）。": "出したカードは<code>捨て札</code>へ。ただし<code>消滅</code>と書かれたカードは 1 戦闘に 1 回きり（消滅置き場へ行き、山札には戻らない）。",
    "打出时清空手牌": "出したときに手札を空にする",
