    "把对手身上已有的中毒 / 剧毒 / 灼伤 / 出血层数全部翻倍。层数得先铺起来，空着翻不出东西。使用后销毁。": "相手にすでに付いているどく / もうどく / やけど / しゅっけつの層をすべて倍にする。層は先に積んでおくこと —— 空っぽでは倍にしても何も出ない。使用後消滅。",
