    "造成 {d} 点伤害；对手每有 1 层出血，这一下额外 +20% 威力（最多 +240%）。": "{d} ダメージ。相手のしゅっけつ1層ごとに威力 +20%（最大 +240%）。",
    "造成 {d} 点伤害；对手每有 1 层虚弱，这一下额外 +45% 威力（最多 +180%）。": "{d} ダメージ。相手のじゃくたい 1 層ごとに威力 +45%（最大 +180%）。",
    "造成 {d} 点伤害；对手身上有中毒或剧毒时，这一下额外 +90% 威力。": "{d} ダメージ。相手がどくかもうどくなら威力 +90%。",
    "造成 {d} 点伤害；无视对手一半防御。": "{d} ダメージを与える。相手の防御を半分無視。",
