    "遇见过，但还没打赢过 —— 它还在图鉴上等着。": "出会ったことはあるが、まだ勝てていない。図鑑で待っている。",
    "道具与背包": "アイテムとバッグ",
    "道具怎么用": "アイテムの使い方",
    "遗落的行囊": "落とし荷",
    "遗迹的守门人": "遺跡の門番",
    "遗迹的诅咒": "いせきののろい",
    "遭遇 {name}！": "{name}が現れた！",
    "那只蘑菇现在长得比它的身子还大，而且看起来才是真正在走路的那个。": "あのキノコは今や本体より大きい。しかも本当に歩いているのはキノコのほうらしい。",
    "那就顺着它走。": "なら、流れに任せよう。",
    "那朵菌盖现在比它整个身体都大，而且明显是菌盖在决定往哪走。": "あの傘はもう体全体より大きい。しかも、どこへ進むかを決めているのは明らかに傘のほうだ。",
    "酸液护甲": "とける",
    "里面是一窝被激怒的大针蜂。你跑得比这辈子任何时候都快。\n「对不起对不起对不起呀 ——！」\nHP -{hp}。": "中にいたのは、怒り狂ったスピアーの一団。生まれてからこれほど速く走ったことはない。\n「ごめんなさいごめんなさいごめんなさい —— ！」\nHP -{hp}。",
    "里面是几瓶还算完好的药和一个钱袋。\n「今天运气不错。」\n金币 +{gold}，获得{item} ×1。": "中にはまだ使えそうな薬が何本かと、金貨の袋が入っていた。\n「今日はついてる。」\nゴールド +{gold}、{item} ×1 を手に入れた。",
    "里面有半袋钱和一瓶还没开封的药。你按原样把钱袋口系了回去，然后又解开。\n「我先借用一下。下次见到你再还。」\n金币 +{gold}，获得{item} ×1。": "中には半分ほど残った金と、まだ封の切られていない薬が 1 本。あなたは元通りに金袋の口を結び直してから、また解いた。\n「ちょっとだけ借りるね。次に会ったら返すから。」\nゴールド +{gold}、「{item}」を 1 個獲得。",
    "里面没有小东西，只有一卷用壳膜包着的招式，还有一张卡。\n「诶……是招式，不是小宝宝。那就收下咯。」\n获得「{card}」。": "中には小さな生き物はいなくて、殻膜に包まれたわざがひと巻きと、カードが一枚だけ。\n「え……わざで、赤ちゃんじゃないんだ。じゃあ、もらっておくね。」\n「{card}」を獲得。",
