    "造成 {d} 点伤害，并让对手防御 -30%。": "Deal {d} damage, and lower the foe's Defense by 30%.",
    "造成 {d} 点伤害，并让对手防御 -3。": "Deal {d} damage. Foe's Defense -3.",
