    "造成 {d} 点伤害，给对手 2 层虚弱，本场战斗防御 +4。": "Deal {d} damage, give the foe 2 Weakened. Defense +4 this battle.",
    "造成 {d} 点伤害，自身也受到一部分反冲。": "Deal {d} damage; you take some recoil too.",
    "造成 {d} 点伤害，自身受到 5 点反伤。使用后销毁。": "Deal {d} damage, and take 5 recoil damage yourself. Exhaust.",
